import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/*
 * Test the behavior when creating a discussion board channel with a duplicate code.
 * This test ensures the API enforces uniqueness for the `code` property as required by business rules.
 *
 * Step-by-step plan:
 * 1. Create a channel with a specific `code` (dependency setup).
 * 2. Attempt to create a second channel using the same `code` but different `name` and `description`.
 *    - Expect a validation or conflict error (do NOT expect a successful creation).
 *    - Confirm that the error is thrown and no channel is created.
 *    - (Optionally) If API returns payload, validate it matches error format.
 */
export async function test_api_discussionBoard_test_create_channel_with_duplicate_code(connection: api.IConnection) {
  // 1. First, create an initial channel with a unique code (dependency)
  const code = RandomGenerator.alphaNumeric(6);
  const channel1 = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      code,
      name: "Economics",
      description: "Economics forum channel."
    } satisfies IDiscussionBoardChannel.ICreate
  });
  typia.assert(channel1);

  // 2. Try to create another channel with the same code but a different name/description
  await TestValidator.error("duplicate code should not be allowed")(async () => {
    await api.functional.discussionBoard.channels.post(connection, {
      body: {
        code,
        name: "Duplicate Economics",
        description: "Second creation attempt with same code."
      } satisfies IDiscussionBoardChannel.ICreate
    });
  });
}

