export async function test_api_discussionBoard_test_soft_delete_member_and_account_status(connection: api.IConnection) {
  // Step 1: Register a member
  const memberData: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
