  typia.assert(member);
  TestValidator.equals("precondition - not deleted")(member.deleted_at)(null);
  TestValidator.equals("precondition - is active")(member.is_active)(true);

  // Step 2: Soft-delete the member by UUID
  await api.functional.discussionBoard.members.eraseById(connection, { id: member.id });
  // There is no return value for eraseById

  // Step 3: Confirm member is now marked as deleted
  const memberAfterDelete = await api.functional.discussionBoard.members.post(connection, { body: { ...memberData, email: typia.random<string & tags.Format<"email">>() } });
