  TestValidator.notEquals("new member != deleted")(memberAfterDelete.id)(member.id);

  // Try deleting again - should fail
  await TestValidator.error("Deleting already-deleted member throws error")(async () => {
    await api.functional.discussionBoard.members.eraseById(connection, { id: member.id });
  });

  // Try deleting a non-existent UUID
  await TestValidator.error("Deleting non-existent member throws error")(async () => {
    await api.functional.discussionBoard.members.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // Additional checks for audit/trace and deactivation cannot be simulated without further API for details/listing/login; omitted per provided SDK. If future member listing endpoints are added, assert deleted_at and is_active are correct there too.
}

