 *
 * This test covers searching and paginating tags using a partial keyword via the PATCH /discussionBoard/tags endpoint. It ensures both the filtering and paging logic work as expected by:
 *   1. Creating a fixed set of tags with both matching and non-matching names
 *   2. Searching for tags using a keyword that matches only a subset
 *   3. Providing pagination parameters to control page/limit
 *   4. Verifying the API returns only matching tags, and their count aligns with pagination metadata
 *   5. Testing edge cases, e.g., page overflow returns no results
 *
 * Steps:
 * 1. Create several tags with names like: 'alpha', 'alphabet', 'beta', 'alphonse', etc.
 * 2. PATCH /discussionBoard/tags with name filter 'alph' and limit=2, page=1
 * 3. Confirm that only tags whose names contain 'alph' (case-sensitive, if API behaves that way) are returned
 * 4. Check pagination meta for total, pages, count
 * 5. Try an out-of-bounds page number and validate zero results
 */
export async function test_api_discussionBoard_test_search_tags_with_keyword_filtering_and_pagination(connection: api.IConnection) {
  // 1. Create known tags for search scenario
  const tagsToCreate = [
    { name: "alpha" },
    { name: "alphabet" },
    { name: "beta" },
    { name: "alphonse" },
    { name: "gamma" },
    { name: "delta" }
  ];
  const createdTags: IDiscussionBoardTag[] = [];
  for (const t of tagsToCreate) {
    const tag = await api.functional.discussionBoard.tags.post(connection, {
      body: {
        name: t.name,
        description: (t.name.charAt(0).toUpperCase() + t.name.slice(1)) + " tag"
      } satisfies IDiscussionBoardTag.ICreate,
    });
    typia.assert(tag);
    createdTags.push(tag);
  }
  // 2. Filter/search with name 'alph' and limit=2/page=1
  const keyword = "alph";
  const limit = 2;
  const page = 1;
  const filterResp = await api.functional.discussionBoard.tags.patch(connection, {
    body: {
      name: keyword,
      limit,
      page
    } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(filterResp);
  // 3. Validate filtered tags
  const expected = createdTags.filter(t => t.name.includes(keyword));
  TestValidator.equals("filtered tags count")(filterResp.pagination.records)(expected.length);
  filterResp.data.forEach(t => {
    TestValidator.predicate(`name contains "${keyword}"`)(t.name.includes(keyword));
  });
  // 4. Paging logic: only limit # tag objects returned, and correct total page math
  TestValidator.equals("returned per page")(filterResp.data.length)(Math.min(limit, expected.length));
  const totalPages = Math.ceil(expected.length / limit);
  TestValidator.equals("pagination.pages")(filterResp.pagination.pages)(totalPages);
  // 5. Query with out-of-bounds page (should return no data)
