 * 4. Attempt to upload same attachment as unauthenticated user (should fail)
 * 5. Attempt to upload with missing required fields (should fail): missing file_name, and missing both discussion_board_post_id & discussion_board_comment_id
 * 6. Attempt to upload duplicate content_hash (should fail, deduplication enforced)
 * 7. Attempt to upload referencing invalid post id (should fail with foreign key error)
 */
export async function test_api_discussionBoard_test_create_attachment_with_valid_and_invalid_data(connection: api.IConnection) {
  // Step 1: Register member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
