  delete missingFileName.file_name;
  await TestValidator.error("missing file_name fails")(async () => {
    await api.functional.discussionBoard.attachments.post(connection, { body: missingFileName as any });
  });

  // Step 5.2: Missing both post_id and comment_id
  const missingParent = { ...validAttachmentInput, discussion_board_post_id: undefined };
  await TestValidator.error("missing parent fails")(async () => {
    await api.functional.discussionBoard.attachments.post(connection, { body: missingParent as any });
  });

  // Step 6: Duplicate content_hash
  await TestValidator.error("duplicate content_hash fails")(async () => {
    await api.functional.discussionBoard.attachments.post(connection, { body: validAttachmentInput });
  });

  // Step 7: Invalid parent post id
  const invalidParent = { ...validAttachmentInput, discussion_board_post_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("invalid parent id fails")(async () => {
