import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test successful soft-deletion of a guest session (by UUID) by an administrator, with audit verification.
 *
 * This test ensures administrators can delete guest sessions for compliance or abuse, while preserving audit records per requirements.
 *
 * Workflow:
 * 1. Register a new discussion board member with assumed administrator authority (required for delete).
 * 2. Create a guest session (for deletion target).
 * 3. Delete the guest session by its UUID, as the admin.
 * 4. Ensure the result entity includes a non-null `deleted_at` timestamp (soft-deletion, not hard delete) — audit requirement.
 * 5. (Business rule) Confirm all entity fields, except for deletion, are preserved for traceability. Check ID, session_token, IP, time fields, and that deleted_at is updated.
 * 6. As direct guest access is not part of the provided endpoints, skip guest retrieval after deletion — but document that in real systems, access after deletion should be forbidden except via audit.
 * 7. No further retrieval is attempted since there are no guest-get endpoints. Confirm that previously deleted entity could be audited (i.e., data is not lost).
 * 8. (Edge) Do not attempt to delete already-deleted guest further, as error handling for that is outside the test scope with available API functions.
 */
export async function test_api_discussionBoard_guests_test_delete_guest_session_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin (discussion board member)
  const admin: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  // (No explicit admin login in API; assume test account is privileged for test context)

  // 2. Create a guest session
  const guest: IDiscussionBoardGuest = await api.functional.discussionBoard.guests.post(connection, {
    body: {
      session_token: RandomGenerator.alphaNumeric(12),
      ip_address: "127.0.0.1",
      user_agent: "test-agent",
      expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1 hour from now
    } satisfies IDiscussionBoardGuest.ICreate,
  });
  typia.assert(guest);

  // 3. Delete the guest session (admin privilege assumed)
  const deleted: IDiscussionBoardGuest = await api.functional.discussionBoard.guests.eraseById(connection, {
    id: guest.id,
  });
  typia.assert(deleted);

  // 4. Assert the deleted record includes deleted_at (soft delete)
  TestValidator.predicate("should have soft-deletion timestamp")(!!deleted.deleted_at);

  // 5. Confirm all guest entity properties preserved for audit (except deleted_at change)
  TestValidator.equals("soft-deleted guest id matches original")(deleted.id)(guest.id);
  TestValidator.equals("soft-deleted session token matches")(deleted.session_token)(guest.session_token);
  TestValidator.equals("soft-deleted ip matches")(deleted.ip_address)(guest.ip_address);
  TestValidator.equals("soft-deleted user agent matches")(deleted.user_agent)(guest.user_agent);
  TestValidator.equals("soft-deleted expiration matches")(deleted.expires_at)(guest.expires_at);

  // 6. (No guest-get endpoint to check forbidden access; would check here in real audit systems)

  // 7. Ensure entity record is preserved for audit
  TestValidator.predicate("audit log: data is still present after soft delete")(!!deleted.id && !!deleted.session_token);
}

