import type { IDiscussionBoardVoteType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardVoteType";
import type { IPageIDiscussionBoardVoteType } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardVoteType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of discussion board vote types as an administrator.
 *
 * This E2E test validates the listing, searching, filtering, and pagination of vote types which define system-level voting operations (such as upvote/downvote/funny) for the discussion board system. Only an admin can access this endpoint.
 *
 * Steps:
 * 1. Create several distinct vote types to ensure the dataset is suitable for testing filtering and pagination. Each vote type includes a unique code, name, and optionally a description.
 * 2. Retrieve all vote types using the patch endpoint. Assert that the created types are present and that pagination info matches number of created records.
 * 3. Filter by exact code, name, and partial matches on name & description to ensure only appropriate records are returned.
 * 4. Test pagination by limiting the results (e.g., limit=2, page=1 and page=2), and verify correct partitioning of data and accurate pagination metadata.
 * 5. Attempt to query with filter values that do not match any records and validate that the result list is empty, but pagination info reflects the query appropriately.
 * 6. If possible, perform ordering and validate the order of returned records. (Skip if unsupported by API.)
 */
export async function test_api_discussionBoard_test_list_vote_types_with_filters_as_administrator(
  connection: api.IConnection,
) {
  // Step 1: Setup - create several vote types.
  const voteTypes = [
    {
      code: "upvote",
      name: "Upvote",
      description: "Positive endorsement"
    },
    {
      code: "downvote",
      name: "Downvote",
      description: "Negative feedback"
    },
    {
      code: "funny",
      name: "Funny",
      description: "Expresses amusement"
    }
  ];
  const createdTypes = [];
  for (const vt of voteTypes) {
    const created = await api.functional.discussionBoard.voteTypes.post(connection, { body: vt });
    typia.assert(created);
    createdTypes.push(created);
  }

  // Step 2: Retrieve all vote types - no filters
  const allResult = await api.functional.discussionBoard.voteTypes.patch(connection, { body: {} });
  typia.assert(allResult);
  const allCodes = createdTypes.map(t => t.code);
  for (const code of allCodes) {
    TestValidator.predicate(`voteType code exists: ${code}`)(
      allResult.data.some(t => t.code === code)
    );
  }
  TestValidator.equals("total records matches")(
    allResult.pagination.records >= voteTypes.length
  )(true);

  // Step 3: Exact code filter
  const filterResult = await api.functional.discussionBoard.voteTypes.patch(connection, { body: { code: "funny" } });
  typia.assert(filterResult);
  TestValidator.equals("filtered - only 'funny'")(filterResult.data.length)(1);
  TestValidator.equals("filtered item code")(
    filterResult.data[0].code
  )("funny");

  // Step 4: Name partial filter & description contains
  const partialResult = await api.functional.discussionBoard.voteTypes.patch(connection, { body: { name: "vote" } });
  typia.assert(partialResult);
  TestValidator.predicate("all names contain 'vote' string")(
    partialResult.data.every(t => t.name.toLowerCase().includes("vote"))
  );

  // Step 5: Pagination test - limit 2 per page
  const page1 = await api.functional.discussionBoard.voteTypes.patch(connection, { body: { limit: 2, page: 1 } });
  typia.assert(page1);
  TestValidator.equals("max 2 results on page 1")(page1.data.length <= 2)(true);
  TestValidator.equals("pagination: limit")(
    page1.pagination.limit
  )(2);
  // Fetch page 2
  const page2 = await api.functional.discussionBoard.voteTypes.patch(connection, { body: { limit: 2, page: 2 } });
  typia.assert(page2);
  TestValidator.equals("pagination: page 2 current")(
    page2.pagination.current
  )(2);

  // Step 6: No match filter (should be empty result)
  const noneResult = await api.functional.discussionBoard.voteTypes.patch(connection, { body: { code: "nonexistenttype" } });
  typia.assert(noneResult);
  TestValidator.equals("empty result for nonexistent code")(noneResult.data.length)(0);
}

