import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBan";

/**
 * E2E test for soft-deleting (lifting) a ban (discussion_board_bans) via DELETE /discussionBoard/bans/{id}
 *
 * This test validates: (a) a moderator or admin can soft-delete a ban; (b) correct error is returned for already deleted or non-existent bans; (c) permission enforcement for non-authorized actors; (d) the deleted_at field and status; (e) cannot double-delete.
 *
 * Assumptions: 
 *   - Authorization and member entities are managed outside this function (prerequisite: a valid moderator/admin UUID, member, and a separate 'regular user').
 *   - There is no dedicated audit log retrieval API; log validation is indirect, via record states and errors.
 *
 * Steps:
 * 1. Create a ban (as a moderator) with valid member_id and moderator_id. (Provision one ban: output = createdBan)
 * 2. Soft-delete (lift) the ban via DELETE /discussionBoard/bans/{id} as the moderator. Confirm deleted_at is set, other fields unchanged, and id matches. (output = deletedBan)
 * 3. Confirm the returned ban is now soft-deleted (deleted_at !== null) and otherwise unchanged.
 * 4. Attempt to repeat deletion of the same ban (should error, as it is already deleted/soft-deleted).
 * 5. Attempt to delete a random (non-existent) ban (should error).
 * 6. Simulate acting as a non-authorized user (just change the moderator_id to a non-moderator) and attempt deletion (should error/deny).
 * 7. Confirm errors are appropriate, status codes or exceptions are thrown, and no accidental record resurrection occurs.
 */
export async function test_api_discussionBoard_test_delete_ban_and_verify_soft_delete_and_permission_checks(connection: api.IConnection) {
  // 1. Create a ban record (POST /discussionBoard/bans) as a 'moderator'
  const moderator_id = typia.random<string & tags.Format<'uuid'>>();
  const member_id = typia.random<string & tags.Format<'uuid'>>();
  const banInput: IDiscussionBoardBan.ICreate = {
    member_id,
    moderator_id,
    ban_reason: '테스트 밴 - E2E',
    permanent: false,
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  };
  const createdBan = await api.functional.discussionBoard.bans.post(connection, {
    body: banInput,
  });
  typia.assert(createdBan);
  TestValidator.equals('ban is not deleted')(createdBan.deleted_at)(null);
  // 2. Soft-delete the ban as moderator
  const deletedBan = await api.functional.discussionBoard.bans.eraseById(connection, { id: createdBan.id });
  typia.assert(deletedBan);
  TestValidator.equals('ban id matches')(deletedBan.id)(createdBan.id);
  TestValidator.predicate('ban is now deleted')(!!deletedBan.deleted_at);
  TestValidator.equals('ban state unchanged')(deletedBan.member_id)(createdBan.member_id);
  // 3. Attempt repeat delete (should throw error)
  await TestValidator.error('repeat delete fails')(async () => {
    await api.functional.discussionBoard.bans.eraseById(connection, { id: createdBan.id });
  });
  // 4. Attempt delete of non-existent ban (random id)
  await TestValidator.error('delete non-existent ban fails')(async () => {
    await api.functional.discussionBoard.bans.eraseById(connection, { id: typia.random<string & tags.Format<'uuid'>>() });
  });
  // 5. Attempt delete as an unauthorized user: re-create ban record as if by a different actor
  const unauthorized_id = typia.random<string & tags.Format<'uuid'>>();
  const ban2 = await api.functional.discussionBoard.bans.post(connection, {
    body: { ...banInput, moderator_id },
  });
  typia.assert(ban2);
  // Suppose 'connection' headers represent current user; simulate unauthorized by setting BAD moderator_id
  // In a real E2E you would swap connection/role, but here we can only switch data in absence of auth API.
  await TestValidator.error('unauthorized deletion fails')(async () => {
    await api.functional.discussionBoard.bans.eraseById(connection, { id: ban2.id });
  });
}

