import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Validate retrieval of a single search history record by unique ID.
 *
 * This test ensures that, as an authorized user (member or admin),
 * retrieving a search history entry by its unique ID returns exactly the fields
 * recorded at creation: search keywords, actor/user UUID, filters (if present),
 * search context, and time performed.
 *
 * Business rules to enforce/validate:
 * 1. A member can only retrieve their own search history by ID, not anyone else's (check privacy enforcement between different users).
 * 2. An admin can retrieve any user’s search history entry by ID (cross-user access permitted).
 *
 * Test process:
 * 1. Create two members and one admin; each gets a unique actor_id.
 * 2. Member 1 logs a search history; Member 2 logs a different one.
 * 3. As Member 1:
 *    - Retrieve their own search history by ID (expect exact match for all data fields).
 *    - Attempt to retrieve Member 2's search history by ID (expect error due to forbidden access).
 * 4. As Admin:
 *    - Retrieve both Member 1's and Member 2's search histories by ID (both must succeed and match data submitted).
 * 5. Check that all fields in the returned records from successful gets match exactly the data supplied/created at POST time.
 * 6. Ensure attempt by Member 1 to retrieve Member 2’s record returns access denied or the appropriate API error.
 */
export async function test_api_discussionBoard_test_get_search_history_by_valid_id(connection: api.IConnection) {
  // 1. Create two members and one admin; each gets actor_id
  const member1Id = typia.random<string & tags.Format<"uuid">>();
  const member2Id = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  // No authentication API is provided in context, so we assume actor_id acts as the role switch here

  // 2. Member 1 logs a search history
  const history1Body: IDiscussionBoardSearchHistory.ICreate = {
    actor_id: member1Id,
    keyword: "nestjs e2e testing", // keyword as in real search
    filters: JSON.stringify({ tag: "typescript" }),
    search_context: "board_page_A"
  };
  const history1 = await api.functional.discussionBoard.searchHistories.post(connection, { body: history1Body });
  typia.assert(history1);

  //    Member 2 logs a different search history
  const history2Body: IDiscussionBoardSearchHistory.ICreate = {
    actor_id: member2Id,
    keyword: "openai ai agent",
    filters: null,
    search_context: null,
  };
  const history2 = await api.functional.discussionBoard.searchHistories.post(connection, { body: history2Body });
  typia.assert(history2);

  // 3. As Member 1: retrieve their own search history by ID
  // (Assume role is switched by using member1Id as context)
  const gotHistory1 = await api.functional.discussionBoard.searchHistories.getById(connection, { id: history1.id });
  typia.assert(gotHistory1);
  TestValidator.equals("history1 fields match")(gotHistory1.actor_id)(history1Body.actor_id);
  TestValidator.equals("history1 keyword matches")(gotHistory1.keyword)(history1Body.keyword);
  TestValidator.equals("history1 filters matches")(gotHistory1.filters)(history1Body.filters);
  TestValidator.equals("history1 context matches")(gotHistory1.search_context)(history1Body.search_context);

  // 3b. As Member 1: attempt to retrieve Member 2's history (should fail - forbidden)
  await TestValidator.error("member cannot get other member's history")(async () => {
    await api.functional.discussionBoard.searchHistories.getById(connection, { id: history2.id });
