/**
 * Test failure of guest session creation when required data is missing or invalid.
 *
 * This test targets the POST /discussionBoard/guests endpoint. It verifies that the API enforces strict validation rules by returning validation errors and refusing to create a guest session when required fields are missing or invalid in the request payload.
 *
 * Precondition: Ensure there is at least one administrator account in the system (dependency: POST /discussionBoard/members).
 *
 * Business context: Session management for guests must be robust, with required metadata captured for every guest. Failure to enforce required fields risks audit, compliance, and abuse tracking issues. This test ensures no incomplete guest entities are created in such cases.
 *
 * The test will:
 * 1. Set up prerequisite member (admin) account, if necessary.
 * 2. Attempt to create a guest session with missing required field(s) (e.g., no ip_address, no session_token, or no expires_at).
 * 3. Attempt to create a guest session with an explicitly null ip_address or expires_at, or with blank session_token.
 * 4. Attempt to create a guest session omitting optional user_agent (should succeed, not fail).
 * 5. Assert the API rejects invalid requests with appropriate error responses (e.g., HTTP 400) and does not persist any entity for invalid submissions.
 *
 * Steps:
 * - Step 1: Register a discussion board member as admin (using valid synthetic data).
 * - Step 2: For each invalid or incomplete payload variant, call POST /discussionBoard/guests and assert an error is returned (using TestValidator.error()).
 * - Step 3: As a control, submit a valid payload omitting only the optional user_agent and assert successful creation of the guest session.
 */
export async function test_api_discussionBoard_test_create_guest_session_missing_required_fields(
  connection: api.IConnection,
) {
  // Step 1: Create prerequisite admin member account with plausible random data.
  const adminData = {
    username: RandomGenerator.alphaNumeric(8),
