  } satisfies IDiscussionBoardMember.ICreate;
  const admin = await api.functional.discussionBoard.members.post(connection, { body: adminData });
  typia.assert(admin);

  // Step 2: Attempt guest session creation with missing or invalid payloads.
  // a) Missing ip_address
  TestValidator.error("missing ip_address should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        session_token: RandomGenerator.alphaNumeric(32),
        // ip_address missing
        expires_at: new Date(Date.now() + 3600_000).toISOString(),
      } as any, // Will fail type check, skip for type safety, but shown for concept
    })
  );

  // b) Missing session_token
  TestValidator.error("missing session_token should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        ip_address: "198.51.100.1",
        expires_at: new Date(Date.now() + 3600_000).toISOString(),
      } as any,
    })
  );

  // c) Missing expires_at
  TestValidator.error("missing expires_at should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        session_token: RandomGenerator.alphaNumeric(32),
        ip_address: "198.51.100.2",
      } as any,
    })
  );

  // d) ip_address null
  TestValidator.error("ip_address null should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        session_token: RandomGenerator.alphaNumeric(32),
        ip_address: null,
        expires_at: new Date(Date.now() + 3600_000).toISOString(),
      } as any,
    })
  );

  // e) expires_at null
  TestValidator.error("expires_at null should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        session_token: RandomGenerator.alphaNumeric(32),
        ip_address: "198.51.100.3",
        expires_at: null,
      } as any,
    })
  );

  // f) session_token blank
  TestValidator.error("session_token blank should fail")(() =>
    api.functional.discussionBoard.guests.post(connection, {
      body: {
        session_token: "",
        ip_address: "198.51.100.4",
        expires_at: new Date(Date.now() + 3600_000).toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
