    body: {
      session_token: RandomGenerator.alphaNumeric(32),
      ip_address: "198.51.100.5",
      user_agent: null,
      expires_at: new Date(Date.now() + 3600_000).toISOString(),
    } satisfies IDiscussionBoardGuest.ICreate,
  });
  typia.assert(resultNullUserAgent);
  TestValidator.predicate("null user_agent accepted")(!!resultNullUserAgent && resultNullUserAgent.user_agent === null);

  // h) Omitting user_agent (should succeed, as it's optional)
  const resultNoUserAgent = await api.functional.discussionBoard.guests.post(connection, {
    body: {
      session_token: RandomGenerator.alphaNumeric(32),
      ip_address: "198.51.100.6",
      expires_at: new Date(Date.now() + 3600_000).toISOString(),
    } satisfies IDiscussionBoardGuest.ICreate,
  });
  typia.assert(resultNoUserAgent);
  TestValidator.predicate("user_agent omitted accepted")(!!resultNoUserAgent && (!('user_agent' in resultNoUserAgent) || resultNoUserAgent.user_agent == null));
}

