import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test thread creation with valid and invalid payloads and user roles.
 *
 * This test validates:
 * 1. Thread creation with valid data by a registered member (happy path)
 * 2. Attempting to create a thread with missing required fields (should fail)
 * 3. Invalid title/body lengths (should fail)
 * 4. Using an invalid/nonexistent category (should fail)
 * 5. Attempting creation as a guest (should fail)
 * 6. (If possible) Simulate a banned/inactive member making request (should fail)
 * 7. The returned thread has correct creator association and is open by default
 *
 * Dependencies handled:
 * - Register a member account to perform authenticated thread creation
 * - Create a valid category for threads
 *
 * Steps:
 * 1. Register a member using the discussionBoard members API
 * 2. Create a category using the discussionBoard categories API
 * 3. Create a thread with all required fields using the member
 *    - Assert thread is created, is_open = false, is_pinned = false, correct creator/category
 * 4. Attempt to create a thread with each required field missing in turn (should error)
 * 5. Attempt to create a thread with too short or empty title/body
 * 6. Attempt to create a thread with an invalid/nonexistent category
 * 7. Attempt to create a thread as a guest (no member context)
 * 8. (If possible) Attempt to create a thread with an inactive/banned member account
 */
export async function test_api_discussionBoard_test_create_thread_with_valid_and_invalid_data(connection: api.IConnection) {
  // Step 1: Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // Step 2: Create a category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
  };
  const category = await api.functional.discussionBoard.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // Step 3: Create thread with valid required data as member
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_member_id: member.id,
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const thread = await api.functional.discussionBoard.threads.post(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("creator id")(thread.discussion_board_member_id)(member.id);
  TestValidator.equals("category id")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("is_open is false by default")(!thread.is_closed)(true);
  TestValidator.equals("is_pinned is false by default")(thread.is_pinned)(false);

  // Step 4: Attempt to create thread with missing required fields
  for (const missing of ["discussion_board_member_id", "discussion_board_category_id", "title", "body"] as const) {
    const partial: any = { ...threadInput };
    delete partial[missing];
    await TestValidator.error(`missing ${missing}`)(async () =>
      api.functional.discussionBoard.threads.post(connection, { body: partial })
    );
  }

  // Step 5: Invalid title/body length
  const tooShortInputs: [keyof IDiscussionBoardThread.ICreate, string][] = [
    ["title", ""],
    ["title", "a"],
    ["body", ""],
    ["body", "a"],
  ];
  for (const [field, value] of tooShortInputs) {
    const invalidInput = { ...threadInput, [field]: value };
    await TestValidator.error(`invalid ${field} length`)(async () =>
      api.functional.discussionBoard.threads.post(connection, { body: invalidInput })
    );
  }

  // Step 6: Nonexistent category id
  const badCategoryInput = { ...threadInput, discussion_board_category_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("invalid category id")(async () =>
    api.functional.discussionBoard.threads.post(connection, { body: badCategoryInput })
  );

  // Step 7: Attempt as guest (simulate guest/no member context)
  // Here we simulate missing member context by omitting a registration step and using a new connection
  const guestThreadInput: IDiscussionBoardThread.ICreate = {
    ...threadInput,
    discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("guest/unregistered member cannot create thread")(async () =>
    api.functional.discussionBoard.threads.post(connection, { body: guestThreadInput })
  );

  // Step 8: Inactive member cannot create
  // Deactivate the member (simulate, since there is no direct API to deactivate)
  // If the API enforced is_active check, this would throw; but as there is no deactivation API, skip if not possible.
}

