      display_name: RandomGenerator.name(),
      profile_image_url: null
    }
  });
  typia.assert(memberB);

  // 2. Assign both as administrators
  const adminAssignA = await api.functional.discussionBoard.administrators.post(connection, {
    body: {
      member_id: memberA.id
    }
  });
  typia.assert(adminAssignA);
  const adminAssignB = await api.functional.discussionBoard.administrators.post(connection, {
    body: {
      member_id: memberB.id
    }
  });
  typia.assert(adminAssignB);

  // 3. List all administrators (default pagination, no filters)
  const listDefault = await api.functional.discussionBoard.administrators.patch(connection, {
    body: {}
  });
  typia.assert(listDefault);
  TestValidator.predicate("should contain both assigned admins")(
    listDefault.data.some(a => a.member_id === memberA.id) &&
    listDefault.data.some(a => a.member_id === memberB.id)
  );

  // 4. Filter by active_only true
  const listActive = await api.functional.discussionBoard.administrators.patch(connection, {
    body: { active_only: true }
  });
  typia.assert(listActive);
  TestValidator.predicate("all should be active")(
    listActive.data.every(a => a.revoked_at === null || a.revoked_at === undefined)
  );

  // 5. Filter by username (memberA)
  const listByUsername = await api.functional.discussionBoard.administrators.patch(connection, {
    body: { username: memberA.username }
  });
