    TestValidator.equals("page 2")(paged2.pagination.current)(2);
    TestValidator.equals("page size")(paged2.data.length)(1);
  }

  // 7. No results case: use non-existent username
  const emptyList = await api.functional.discussionBoard.administrators.patch(connection, {
    body: { username: "nonexistent_test_user" }
  });
