 * 4. As administrator, list all mentions and verify all records are included regardless of sender/recipient.
 * 5. Use patch advanced filter (mentioned_member_id/actor_member_id, pagination) to retrieve subsets, and confirm returned records are correct per filter.
 * 6. Verify both 'sent' and 'received' mention flows are visible to the administrator as permitted by RBAC.
 */
export async function test_api_discussionBoard_test_list_mentions_as_moderator_includes_all_mentions(
  connection: api.IConnection,
) {
  // 1. Create three members: two regular, one future admin
  const password = RandomGenerator.alphaNumeric(12);
