  typia.assert(member1);
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: password, display_name: RandomGenerator.name(), profile_image_url: null } });
  typia.assert(member2);
  const adminMember = await api.functional.discussionBoard.members.post(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: password, display_name: RandomGenerator.name(), profile_image_url: null } });
  typia.assert(adminMember);

  // 2. Assign admin privileges to adminMember
  const admin = await api.functional.discussionBoard.administrators.post(connection, { body: { member_id: adminMember.id } });
  typia.assert(admin);

  // 3. Create cross-mention events
  const content_type_a = "post";
  const content_type_b = "comment";
  const content_id_a = typia.random<string & tags.Format<"uuid">>();
  const content_id_b = typia.random<string & tags.Format<"uuid">>();
  const mention1 = await api.functional.discussionBoard.mentions.post(connection, { body: { mentioned_member_id: member2.id, content_type: content_type_a, content_id: content_id_a } });
  typia.assert(mention1);
  const mention2 = await api.functional.discussionBoard.mentions.post(connection, { body: { mentioned_member_id: member1.id, content_type: content_type_b, content_id: content_id_b } });
  typia.assert(mention2);
  const mention3 = await api.functional.discussionBoard.mentions.post(connection, { body: { mentioned_member_id: member1.id, content_type: content_type_a, content_id: content_id_b } });
  typia.assert(mention3);

  // 4. As admin: search all mentions (no filters), expect at least mention1, 2, 3
  const allMentions = await api.functional.discussionBoard.mentions.patch(connection, { body: {} });
  typia.assert(allMentions);
  const allMentionIds = allMentions.data.map((m) => m.id);
  TestValidator.predicate("all created mentions are found")(allMentionIds.includes(mention1.id) && allMentionIds.includes(mention2.id) && allMentionIds.includes(mention3.id));

  // 5. Filter: mentions where mentioned_member_id==member1.id (member1 was mentioned)
  const mentionsOfMember1 = await api.functional.discussionBoard.mentions.patch(connection, { body: { mentioned_member_id: member1.id } });
  typia.assert(mentionsOfMember1);
  TestValidator.predicate("mentions of member1 match")(mentionsOfMember1.data.every(m => m.mentioned_member_id === member1.id));
  // Ensure known mentions present
  TestValidator.predicate("includes some known mentions for member1")(mentionsOfMember1.data.some(m => m.id === mention2.id || m.id === mention3.id));

  // 6. Filter: mentions sent by member1 (actor_member_id==member1.id)
  const mentionsFromMember1 = await api.functional.discussionBoard.mentions.patch(connection, { body: { actor_member_id: member1.id } });
  typia.assert(mentionsFromMember1);
  TestValidator.predicate("mentions sent by member1")(mentionsFromMember1.data.every(m => m.actor_member_id === member1.id));

  // 7. Filter: combined filters and pagination
  const pagedResult = await api.functional.discussionBoard.mentions.patch(connection, { body: { page: 1, limit: 2 } });
  typia.assert(pagedResult);
  TestValidator.equals("limit respected")(pagedResult.data.length)(Math.min(2, allMentions.data.length));
}

