import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";

/**
 * Test unauthorised access to subscription detail.
 *
 * Ensure that a user cannot retrieve the details of a discussion board subscription that belongs to another member, preserving privacy and enforcing security compliance.
 *
 * Steps:
 * 1. Register Member A (the subscription owner)
 * 2. Register Member B (unauthorized user)
 * 3. As Member A, create a subscription
 * 4. Switch to Member B and attempt to access Member A's subscription via GET
 *    /discussionBoard/subscriptions/{id}
 * 5. Validate that access is denied (forbidden or not found)
 */
export async function test_api_discussionBoard_test_get_subscription_detail_for_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Register Member A (the subscription owner)
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberA: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: memberAEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);

  // 2. Register Member B (unauthorized user)
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberB: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: memberBEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. Switch context/authentication to Member A and create a subscription
  await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: memberA.username,
      email: memberA.email,
      hashed_password: memberA.hashed_password,
      display_name: memberA.display_name,
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  const subscription: IDiscussionBoardSubscription = await api.functional.discussionBoard.subscriptions.post(connection, {
    body: {
      target_type: "thread",
      target_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IDiscussionBoardSubscription.ICreate,
  });
  typia.assert(subscription);

  // 4. Switch context/authentication to Member B
  await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: memberB.username,
      email: memberB.email,
      hashed_password: memberB.hashed_password,
      display_name: memberB.display_name,
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });

  // 5. Attempt to fetch subscription owned by Member A (as Member B) and expect forbidden/not found
  await TestValidator.error("unauthorized subscription detail fetch fails")(() =>
    api.functional.discussionBoard.subscriptions.getById(connection, {
      id: subscription.id,
    })
  );
}

