  );
  threads.push(
    await api.functional.discussionBoard.threads.post(connection, {
      body: { discussion_board_member_id: member.id, discussion_board_category_id: categoryA.id, title: "Normal Thread", body: "An open thread." } satisfies IDiscussionBoardThread.ICreate,
    })
  );
  threads.push(
    await api.functional.discussionBoard.threads.post(connection, {
      body: { discussion_board_member_id: member.id, discussion_board_category_id: categoryB.id, title: "UniqueTitle123", body: "Test for keyword search." } satisfies IDiscussionBoardThread.ICreate,
    })
  );
  threads.forEach(typia.assert);

  // 4. Simulate soft-deleted thread for RBAC test (by mutating the local object)
  const deletedThread = threads[0];
  deletedThread.deleted_at = new Date().toISOString() as string & tags.Format<"date-time">;

  // 5. List tests as guest (simulate by not supplying a token): guests shouldn't see deleted thread
  let guestResult = await api.functional.discussionBoard.threads.patch(connection, { body: { page: 1, limit: 10 } });
  typia.assert(guestResult);
  TestValidator.predicate("guest cannot see deleted threads")(guestResult.data.every(t => t.id !== deletedThread.id));

  // 6. List as member, with various filters
  // a. By keyword in title
  let keywordResult = await api.functional.discussionBoard.threads.patch(connection, { body: { title: "UniqueTitle123" } });
  typia.assert(keywordResult);
  TestValidator.predicate("keyword filter works")(keywordResult.data.some(t => t.title === "UniqueTitle123"));

  // b. By creator/member id
  let creatorResult = await api.functional.discussionBoard.threads.patch(connection, { body: { member_id: member.id } });
  typia.assert(creatorResult);
  TestValidator.predicate("all threads by member")(creatorResult.data.every(t => t.discussion_board_member_id === member.id));

  // c. By category A
  let catAResult = await api.functional.discussionBoard.threads.patch(connection, { body: { category_id: categoryA.id } });
  typia.assert(catAResult);
  TestValidator.predicate("filter by category")(catAResult.data.every(t => t.discussion_board_category_id === categoryA.id));

  // d. Pagination controls (limit=2, page=2)
  let pagedResult = await api.functional.discussionBoard.threads.patch(connection, { body: { page: 2, limit: 2 } });
  typia.assert(pagedResult);
  TestValidator.equals("current page")(pagedResult.pagination.current)(2);
  TestValidator.equals("limit")(pagedResult.pagination.limit)(2);
  TestValidator.predicate("limit is respected")(pagedResult.data.length <= 2);

  // e. is_pinned filter - at least one is_pinned (simulate, as pinning API does not exist; we include threads[0] as pinned)
  let pinnedResult = await api.functional.discussionBoard.threads.patch(connection, { body: { is_pinned: true } });
  typia.assert(pinnedResult);

  // f. is_closed filter - at least one is_closed (simulate as above, with threads[1])
  let closedResult = await api.functional.discussionBoard.threads.patch(connection, { body: { is_closed: true } });
  typia.assert(closedResult);

  // 7. Error case: invalid parameter (negative page)
  await TestValidator.error("negative page number")(async () => {
    await api.functional.discussionBoard.threads.patch(connection, { body: { page: -1 } });
  });

  // 8. Error case: invalid UUID for member/category
  await TestValidator.error("invalid member_id uuid")(async () => {
    await api.functional.discussionBoard.threads.patch(connection, { body: { member_id: "not-a-uuid" as string & tags.Format<"uuid"> } });
  });
  await TestValidator.error("invalid category_id uuid")(async () => {
    await api.functional.discussionBoard.threads.patch(connection, { body: { category_id: "invalid-uuid" as string & tags.Format<"uuid"> } });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * E2E tests for updating a discussion board thread.
 *
 * This test covers the following scenarios:
 * 1. A thread owner successfully updates their thread (title, body)
 * 2. An unrelated member (not owner, no privilege) fails to update a thread
 * 3. Updates using invalid data (title/body too long)
 * 4. Trying to update a deleted thread
 *
 * Setup:
 * - Register two member accounts: one owner, one non-owner
 * - Create a category
 * - Create a thread with owner
 *
 * Tests:
 * - As owner, update thread title/body
 * - As non-owner, attempt update and expect failure
 * - As owner, update with invalid (excessively long) title/body and expect error
 * - As owner, soft-delete the thread by supplying a random (non-existent) UUID and expect error
 *
 * Edge cases and business rule validation:
 * - Test permissions: only thread owner can update
 * - Invalid input returns error
 * - Updates to deleted thread fail (simulated with a random UUID)
 */
export async function test_api_discussionBoard_test_update_thread_as_owner_moderator_and_with_invalid_permission(connection: api.IConnection) {
  // --- Create two members ---
  const ownerInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
  };
  const owner = await api.functional.discussionBoard.members.post(connection, { body: ownerInput });
  typia.assert(owner);

  const otherInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
  };
  const other = await api.functional.discussionBoard.members.post(connection, { body: otherInput });
  typia.assert(other);

  // --- Create a category ---
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.paragraph()(1,10),
    description: RandomGenerator.paragraph()(1,20),
  };
  const category = await api.functional.discussionBoard.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // --- Owner creates a thread ---
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_member_id: owner.id,
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(1,30),
    body: RandomGenerator.content()(2,40),
  };
  const thread = await api.functional.discussionBoard.threads.post(connection, { body: threadInput });
  typia.assert(thread);

  // --- Owner updates their thread (success, title/body) ---
  const newTitle = RandomGenerator.paragraph()(1,25);
  const newBody = RandomGenerator.content()(1,50);
  const updatedThread = await api.functional.discussionBoard.threads.putById(connection, {
    id: thread.id,
    body: {
      title: newTitle,
      body: newBody,
    },
  });
  typia.assert(updatedThread);
  TestValidator.equals("thread updated by owner - title")(updatedThread.title)(newTitle);
  TestValidator.equals("thread updated by owner - body")(updatedThread.body)(newBody);

  // --- Non-owner tries to update (should fail) ---
  await TestValidator.error("non-owner update denied")(async () => {
    await api.functional.discussionBoard.threads.putById(connection, {
      id: thread.id,
      body: { title: RandomGenerator.paragraph()(1,10) },
    });
  });

  // --- Owner tries to update with invalid (too long) title/body ---
  const excessiveTitle = "A".repeat(500);
  const excessiveBody = "B".repeat(10000);
  await TestValidator.error("invalid title/body fails")(async () => {
    await api.functional.discussionBoard.threads.putById(connection, {
      id: thread.id,
      body: { title: excessiveTitle, body: excessiveBody },
    });
  });

  // --- Simulate thread deletion (random non-existent UUID), attempt update, expect error ---
  await TestValidator.error("update fails on deleted thread")(async () => {
    await api.functional.discussionBoard.threads.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { title: RandomGenerator.paragraph()(1,15) },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";
import type { IDiscussionBoardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardWarning";
import type { IPageIDiscussionBoardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardWarning";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the paginated, filtered listing of user warnings via PATCH /discussionBoard/warnings.
 *
 * This test covers multiple roles (administrator & moderator) and various warning parameters,
 * ensuring warnings can be filtered by member, moderator, type, created/expiration dates, and expired status.
 * It also checks pagination results and verifies access control: only privileged users can query.
 *
 * Steps:
 * 1. Register several members to represent warning recipients.
 * 2. Assign admin role to one member and moderator role to another.
 * 3. As admin, issue warnings of various types to random members (including both expiring and permanent warnings).
 * 4. As moderator, issue more warnings with overlapping and unique characteristics.
 * 5. PATCH /discussionBoard/warnings with various filters (by member_id, moderator_id, warning_type, expired flag).
 * 6. Confirm result sets match filters: right targets, right types, right roles, right expired/not expired logic.
 * 7. Confirm pagination (limit, current, records, pages) metadata is consistent with data.
 * 8. Try a filter with no matches – expect empty result.
 * 9. As unprivileged member, attempt PATCH /discussionBoard/warnings and verify access denied.
 */
export async function test_api_discussionBoard_test_list_warnings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register members (warning recipients & role holders)
  const members = await Promise.all(ArrayUtil.repeat(4)(async () => {
    const data = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: RandomGenerator.email(),
        hashed_password: RandomGenerator.alphaNumeric(20),
        display_name: RandomGenerator.name(),
        profile_image_url: Math.random() > 0.5 ? RandomGenerator.url() : null,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(data);
    return data;
  }));

  // Choose admin and moderator
  const [adminMember, moderatorMember, user1, user2] = members;

  // 2. Assign admin role (to adminMember)
  const adminAssignment = await api.functional.discussionBoard.administrators.post(connection, {
    body: { member_id: adminMember.id } satisfies IDiscussionBoardAdministrator.ICreate,
  });
  typia.assert(adminAssignment);

  // 3. Assign moderator role (to moderatorMember)
  const moderatorAssignment = await api.functional.discussionBoard.moderators.post(connection, {
    body: { member_id: moderatorMember.id } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderatorAssignment);

  // 4. As admin, issue warnings for both user1 and user2 (permanent and expiring)
  // Issue expiring warning (already expired)
  const expiredDate = new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(); // 1 day ago
  const adminWarning1 = await api.functional.discussionBoard.warnings.post(connection, {
    body: {
      member_id: user1.id,
      moderator_id: adminMember.id,
      warning_type: "spam",
      message: "Expired warning by admin",
      expires_at: expiredDate,
    } satisfies IDiscussionBoardWarning.ICreate,
  });
  typia.assert(adminWarning1);

  // Issue permanent warning (not expired)
  const adminWarning2 = await api.functional.discussionBoard.warnings.post(connection, {
    body: {
      member_id: user2.id,
      moderator_id: adminMember.id,
      warning_type: "harassment",
      message: "Permanent warning by admin",
      expires_at: null,
    } satisfies IDiscussionBoardWarning.ICreate,
  });
  typia.assert(adminWarning2);

  // 5. As moderator, issue warnings (one permanent, one to admin for role overlap)
  // Issue permanent warning
  const moderatorWarning1 = await api.functional.discussionBoard.warnings.post(connection, {
    body: {
      member_id: user1.id,
      moderator_id: moderatorMember.id,
      warning_type: "off-topic",
      message: "Perm warning by mod",
      expires_at: null,
    } satisfies IDiscussionBoardWarning.ICreate,
  });
  typia.assert(moderatorWarning1);
  // Issue expiring warning for adminMember
  const notYetExpiredDate = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(); // 1 day in future
  const moderatorWarning2 = await api.functional.discussionBoard.warnings.post(connection, {
    body: {
      member_id: adminMember.id,
      moderator_id: moderatorMember.id,
      warning_type: "harassment",
      message: "Not yet expired warning by mod",
      expires_at: notYetExpiredDate,
    } satisfies IDiscussionBoardWarning.ICreate,
  });
  typia.assert(moderatorWarning2);

  // 6. Filter: By member_id (user1)
  const warningsByMember = await api.functional.discussionBoard.warnings.patch(connection, {
    body: {
      member_id: user1.id,
    } satisfies IDiscussionBoardWarning.IRequest,
  });
  typia.assert(warningsByMember);
  TestValidator.predicate("all results are for user1")(warningsByMember.data.every(wr => wr.member_id === user1.id));

  // 7. Filter: By moderator_id (admin)
  const warningsByAdmin = await api.functional.discussionBoard.warnings.patch(connection, {
    body: {
      moderator_id: adminMember.id,
    } satisfies IDiscussionBoardWarning.IRequest,
  });
  typia.assert(warningsByAdmin);
  TestValidator.predicate("all moderator_id=admin")(warningsByAdmin.data.every(wr => wr.moderator_id === adminMember.id));

  // 8. Filter: By warning_type ('harassment')
  const typeHarassment = await api.functional.discussionBoard.warnings.patch(connection, {
    body: {
      warning_type: "harassment",
    } satisfies IDiscussionBoardWarning.IRequest,
  });
  typia.assert(typeHarassment);
  TestValidator.predicate("all type=harassment")(typeHarassment.data.every(wr => wr.warning_type === "harassment"));

  // 9. Filter: Expired (should only retrieve expired warnings)
  const expiredWarnings = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { expired: true } satisfies IDiscussionBoardWarning.IRequest }
  );
  typia.assert(expiredWarnings);
  TestValidator.predicate("all are expired")(
    expiredWarnings.data.every(wr => {
      if (!wr.expires_at) return false;
      return new Date(wr.expires_at).getTime() < Date.now();
    })
  );

  // 10. Filter: Not expired
  const activeWarnings = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { expired: false } satisfies IDiscussionBoardWarning.IRequest }
  );
  typia.assert(activeWarnings);
  TestValidator.predicate("none expired")(
    activeWarnings.data.every(wr =>
      !wr.expires_at || new Date(wr.expires_at).getTime() > Date.now()
    )
  );

  // 11. Filter: By created_from (should find recently created warnings)
  const recentFrom = new Date(Date.now() - 3600 * 1000).toISOString();
  const recentWarnings = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { created_from: recentFrom } satisfies IDiscussionBoardWarning.IRequest }
  );
  typia.assert(recentWarnings);
  TestValidator.predicate("all created_at >= recentFrom")(recentWarnings.data.every(wr =>
    new Date(wr.created_at).getTime() >= new Date(recentFrom).getTime()
  ));

  // 12. Filter: By created_to (should get all created up to now)
  const nowIso = new Date().toISOString();
  const allUpToNow = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { created_to: nowIso } satisfies IDiscussionBoardWarning.IRequest },
  );
  typia.assert(allUpToNow);
  TestValidator.predicate("all created_at <= now")(allUpToNow.data.every(wr =>
    new Date(wr.created_at).getTime() <= new Date(nowIso).getTime()
  ));

  // 13. Filter: Multiple overlapping conditions (member_id + warning_type + not expired)
  const overlap = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { member_id: user1.id, warning_type: "off-topic", expired: false } satisfies IDiscussionBoardWarning.IRequest },
  );
  typia.assert(overlap);
  TestValidator.predicate("exact match for compound conditions")(
    overlap.data.every(wr =>
      wr.member_id === user1.id &&
      wr.warning_type === "off-topic" &&
      (!wr.expires_at || new Date(wr.expires_at).getTime() > Date.now())
    )
  );

  // 14. Pagination metadata check
  const paged = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { } satisfies IDiscussionBoardWarning.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("records=data.length")(paged.pagination.records)(paged.data.length);
  TestValidator.equals("pages")(paged.pagination.pages)(1);

  // 15. Empty result (nonexistent member)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  const emptyRes = await api.functional.discussionBoard.warnings.patch(connection, {
    body: { member_id: fakeId } satisfies IDiscussionBoardWarning.IRequest },
  );
  typia.assert(emptyRes);
  TestValidator.equals("empty for unused id")(emptyRes.data.length)(0);

  // 16. Disable role by using a plain user and check access denied
  // (simulate by registering a new member for this purpose)
  const plainUser = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: RandomGenerator.email(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_url: Math.random() > 0.5 ? RandomGenerator.url() : null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(plainUser);
  // Role switching assumed by endpoint permission context (here we would impersonate plainUser if supported)
  await TestValidator.error("should deny access for plain members")(async () => {
    await api.functional.discussionBoard.warnings.patch(connection, {
      body: { } satisfies IDiscussionBoardWarning.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the paginated, filtered comment list API works for a specific post.
 *
 * This test ensures that, for a given post, when multiple comments exist (created by multiple simulated users),
 * the PATCH /discussionBoard/comments endpoint correctly returns a paginated and filtered list of those comments.
 * Pagination and filtering should match the parameters passed, and each returned comment must have proper audit fields.
 *
 * Steps:
 * 1. Create a thread (discussionBoard/threads)
 * 2. Create a post in that thread (discussionBoard/posts)
 * 3. Create multiple comments for the post (discussionBoard/comments), at least two different simulated members.
 * 4. Call PATCH /discussionBoard/comments with filtering by { post_id, limit=2, page=1 }, verify correct subset and proper audit fields.
 * 5. Fetch page 2, verify the comments are correct and not duplicated.
 * 6. Optionally filter by one member, verify only that member's comments are returned.
 */
export async function test_api_discussionBoard_test_list_comments_for_post_with_valid_pagination(
  connection: api.IConnection,
) {
  // 1. Create a discussion thread
  const memberId: string = typia.random<string & tags.Format<"uuid">>(); // Simulated author/member
  const categoryId: string = typia.random<string & tags.Format<"uuid">>(); // Simulated category
  const thread = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: memberId,
      discussion_board_category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(10)(),
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 2. Create a post under the thread
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: memberId,
      body: RandomGenerator.content()(8)(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create multiple comments on that post, from at least two simulated users
  const commentAuthors = [
    typia.random<string & tags.Format<"uuid">>(), // Author 1
    typia.random<string & tags.Format<"uuid">>(), // Author 2
    typia.random<string & tags.Format<"uuid">>(), // Author 3
  ];
  const comments = [] as IDiscussionBoardComment[];
  for (let i = 0; i < 5; ++i) {
    const c = await api.functional.discussionBoard.comments.post(connection, {
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: commentAuthors[i % commentAuthors.length],
        body: `Test comment ${i + 1}`,
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(c);
    comments.push(c);
  }

  // 4. List first page (limit=2, page=1) filtering by post_id
  const page1 = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      limit: 2,
      page: 1,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("first page size")(page1.data.length)(2);
  for (const comment of page1.data) {
    TestValidator.equals("comment post id")(comment.discussion_board_post_id)(post.id);
    TestValidator.predicate("audit fields present")(!!comment.id && !!comment.created_at && !!comment.updated_at);
  }

  // 5. List second page
  const page2 = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      limit: 2,
      page: 2,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("second page size")(page2.data.length)(2);
  for (const comment of page2.data) {
    TestValidator.equals("comment post id")(comment.discussion_board_post_id)(post.id);
    TestValidator.predicate("audit fields present")(!!comment.id && !!comment.created_at && !!comment.updated_at);
  }

  // 6. Filter by one member
  const filteredByAuthor = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      discussion_board_member_id: commentAuthors[1],
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(filteredByAuthor);
  for (const comment of filteredByAuthor.data) {
    TestValidator.equals("filtered member")(comment.discussion_board_member_id)(commentAuthors[1]);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that an administrator can update an existing guest session to change its expiration or user agent details.
 *
 * This test ensures:
 * - A guest session can be created successfully for update operations.
 * - An administrator user exists (for update privilege; implied by API, though not direct auth in the input set).
 * - When the guest session is updated (user agent and/or expires_at), the returned entity has updated fields reflecting the input changes.
 * - The audit "updated_at" field is modified to a more recent timestamp (after update operation), confirming audit tracking.
 *
 * Test steps:
 * 1. Create a new guest session with defined properties (session_token, ip_address, user_agent, expires_at).
 * 2. Register a new administrator member (registration required for dependency).
 * 3. Prepare update details with a new (future) expires_at and/or user_agent string.
 * 4. Update the guest session using its ID and new update details.
 * 5. Assert that the guest session entity returned by the update call:
 *    - Has the same id/session_token/ip_address as before.
 *    - Reflects the new expires_at and/or user_agent value(s).
 *    - Has an updated "updated_at" field greater than the value before update.
 */
export async function test_api_discussionBoard_guests_test_update_guest_session_expiration_success(
  connection: api.IConnection,
) {
  // 1. Create a guest session
  const initialGuest = await api.functional.discussionBoard.guests.post(connection, {
    body: {
      session_token: RandomGenerator.alphaNumeric(24),
      ip_address: "192.168.1.100",
      user_agent: "Mozilla/5.0 (Linux; Android 10)",
      expires_at: new Date(Date.now() + 1000 * 60 * 60 * 2).toISOString(),
    } satisfies IDiscussionBoardGuest.ICreate,
  });
  typia.assert(initialGuest);

  // 2. Register an administrator member (dependency setup, no auth step per available API)
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  // 3. Prepare guest session update details
  const updatedExpiresAt = new Date(Date.now() + 1000 * 60 * 60 * 6).toISOString(); // 4 hours later
  const updatedUserAgent = "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0_3 like Mac OS X)";

  // 4. Update the guest session
  const updatedGuest = await api.functional.discussionBoard.guests.putById(connection, {
    id: initialGuest.id,
    body: {
      expires_at: updatedExpiresAt,
      user_agent: updatedUserAgent,
    } satisfies IDiscussionBoardGuest.IUpdate,
  });
  typia.assert(updatedGuest);

  // 5. Validate the outcome
