 * 2. Register another member (as an unrelated user)
 * 3. Register a third member (future moderator)
 * 4. Create a post as the reporter (use random valid thread UUID as placeholder, since thread management is out of scope)
 * 5. File a report referencing the post as the reporter
 * 6. Retrieve the report by ID as the reporter (should succeed and match submission + created object)
 * 7. Retrieve as unrelated member (should receive forbidden/unauthorized)
 * 8. Assign moderator rights
 * 9. Retrieve by ID as moderator & validate
 * 10. Attempt to retrieve a non-existent report
 */
export async function test_api_discussionBoard_test_get_report_detail_by_id_as_reporter_and_moderator(
  connection: api.IConnection,
) {
  // 1. Register reporter (member)
  const reporterEmail = typia.random<string & tags.Format<"email">>();
  const reporterUsername = RandomGenerator.alphaNumeric(9);
  const reporterPassword = RandomGenerator.alphaNumeric(12);

  const reporter = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: reporterUsername,
        email: reporterEmail,
        hashed_password: reporterPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(reporter);

  // 2. Register unrelated member
  const unrelatedEmail = typia.random<string & tags.Format<"email">>();
  const unrelatedUsername = RandomGenerator.alphaNumeric(9);
  const unrelatedPassword = RandomGenerator.alphaNumeric(12);

  const unrelated = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: unrelatedUsername,
        email: unrelatedEmail,
        hashed_password: unrelatedPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(unrelated);

  // 3. Register moderator candidate
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(9);
  const moderatorPassword = RandomGenerator.alphaNumeric(12);

  const moderator = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: moderatorUsername,
        email: moderatorEmail,
        hashed_password: moderatorPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(moderator);

  // 4. Create a post as the reporter (simulate valid thread id)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(
    connection,
    {
      body: {
        discussion_board_thread_id: threadId,
        discussion_board_member_id: reporter.id,
        body: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 5. File a report referencing the post as the reporter
  const reportReason = "Prohibited content";
  const report = await api.functional.discussionBoard.reports.post(
    connection,
    {
      body: {
        reporter_member_id: reporter.id,
        thread_id: null, // Not reporting a thread
        post_id: post.id,
        comment_id: null, // Not reporting a comment
        reason: reportReason,
      } satisfies IDiscussionBoardReport.ICreate,
    },
  );
  typia.assert(report);

  // 6. Retrieve the report as the reporter & validate output
  const readAsReporter = await api.functional.discussionBoard.reports.getById(
    connection,
    { id: report.id },
  );
  typia.assert(readAsReporter);
  TestValidator.equals("report matches ID")(readAsReporter.id)(report.id);
  TestValidator.equals("reporter matches")(readAsReporter.reporter_member_id)(reporter.id);
  TestValidator.equals("post matches")(readAsReporter.post_id)(post.id);
  TestValidator.equals("reason matches")(readAsReporter.reason)(reportReason);

  // 7. Retrieve the report as unrelated member & expect error
  // Simulate login as unrelated member (since no API for login, assume token switch or connect as new user)
  connection.headers.Authorization = unrelated.id;
  await TestValidator.error("unrelated member should not view report")(
    async () => {
      await api.functional.discussionBoard.reports.getById(connection, {
        id: report.id,
      });
    },
  );

  // 8. Assign moderator rights to moderator member
  // Restore to main connection for admin-equivalent rights if required by env
  connection.headers.Authorization = undefined;
  const moderatorAssignment = await api.functional.discussionBoard.moderators.post(
    connection,
    {
      body: {
        member_id: moderator.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(moderatorAssignment);

  // 9. Retrieve by ID as moderator & validate
  connection.headers.Authorization = moderator.id;
  const readAsModerator = await api.functional.discussionBoard.reports.getById(
    connection,
    { id: report.id },
  );
  typia.assert(readAsModerator);
  TestValidator.equals("report ID for moderator")(readAsModerator.id)(report.id);
  TestValidator.equals("moderator assignment permitted")(typeof readAsModerator.status === "string")(true);

  // 10. Attempt to retrieve a non-existent report
  await TestValidator.error("not found for invalid ID")(
    async () => {
      await api.functional.discussionBoard.reports.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate that a notification recipient can update a notification to mark it as read
 *
 * This end-to-end test verifies that:
 * 1. A member account can be registered (will be the notification recipient)
 * 2. A notification is correctly created for that member
 * 3. The member can update the notification to mark it as read
 * 4. After the update:
 *    - The 'read' field for the notification becomes true
 *    - Relevant audit fields (like updated_at, delivered_at) are appropriately updated
 *
 * Test Steps:
 * 1. Register a discussion board member (recipient)
 * 2. Create a notification for that member (with read: false by default)
 * 3. Mark the notification as read (read: true) using the update API
 * 4. Assert that read transitions from false -> true and that audit fields change
 */
export async function test_api_discussionBoard_test_update_notification_mark_as_read_by_recipient(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (recipient)
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
  };
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a notification for the member
  const notifInput: IDiscussionBoardNotification.ICreate = {
    recipient_member_id: member.id,
    trigger_actor_id: null,
    type: "mention",
    content_preview: "You were mentioned in a comment!",
    url: "https://community.example.com/thread/" + RandomGenerator.alphaNumeric(8),
  };
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: notifInput,
  });
  typia.assert(notification);
  TestValidator.equals("Initial notification is unread")(notification.read)(false);

  // 3. Update the notification to mark as read
  const updated = await api.functional.discussionBoard.notifications.putById(connection, {
    id: notification.id,
    body: { read: true },
  });
  typia.assert(updated);

  // 4. Assert read transitions and audit fields change
  TestValidator.equals("Read field after update")(updated.read)(true);
  TestValidator.equals("Member and notification unchanged")(updated.recipient_member_id)(notification.recipient_member_id);
  TestValidator.notEquals("updated_at timestamp changes")(updated.updated_at)(notification.updated_at);
  if (notification.delivered_at && updated.delivered_at) {
    // delivered_at could stay the same or be set if null before
    TestValidator.equals("delivered_at remains or is set")(updated.delivered_at >= notification.delivered_at)(true);
  }
}

