import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate forbidden access to notification list for unauthenticated users.
 *
 * This test checks that attempting to list notifications without authentication
 * returns an authorization error and does not expose notification data. It
 * simulates an unauthenticated API call by stripping any Authorization token
 * from the connection headers and ensures that sensitive notification
 * information cannot be retrieved without proper login.
 *
 * Steps:
 * 1. Remove Authorization header to force unauthenticated context.
 * 2. Prepare an empty notification list request (no filters/pagination).
 * 3. Call the notifications listing endpoint with the unauthenticated connection.
 * 4. Assert that the API call fails with an authorization error.
 * 5. Confirm that no notification information is leaked in the process.
 */
export async function test_api_discussionBoard_test_list_notifications_forbidden_for_unauthenticated_user(
  connection: api.IConnection,
) {
  // 1. Remove Authorization header for unauthenticated request context
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  delete unauthenticatedConnection.headers.Authorization;

  // 2. Prepare a minimal notification list request body
  const requestBody: IDiscussionBoardNotification.IRequest = {};

  // 3. Attempt to list notifications as an unauthenticated user
  // 4. Assert proper authorization error, ensuring private data is not leaked
  await TestValidator.error("Unauthenticated user cannot access notification list")(
    async () => {
      await api.functional.discussionBoard.notifications.patch(
        unauthenticatedConnection,
        { body: requestBody },
      );
    },
  );
}

