import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * Validate that a non-admin user cannot soft-delete a discussion board channel.
 *
 * This test verifies strict role-based access control (RBAC) enforcement for the discussion board channels deletion endpoint.
 * 
 * Steps:
 * 1. Use admin privileges to create a new discussion board channel for setup.
 * 2. (Simulate) As a non-admin user, attempt to soft-delete the channel.
 * 3. Verify that a forbidden or unauthorized error is thrown by the API.
 * 4. No confirmation step for deletion status is possible (no GET-by-id endpoint provided).
 */
export async function test_api_discussionBoard_test_soft_delete_channel_by_non_admin(connection: api.IConnection) {
  // 1. Create channel as admin
  const output: IDiscussionBoardChannel =
    await api.functional.discussionBoard.channels.post(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(1),
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(output);

  // 2. (Simulate) Switch to non-admin by removing admin credentials
  const connectionAsNonAdmin: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      // Remove or nullify privilege header/token as per test infra
      // In a real setup, you would authenticate as a specific non-admin account
      Authorization: undefined,
    },
  };

  // 3. Attempt forbidden delete and expect error
  await TestValidator.error("Non-admin forbidden to delete channel")(async () => {
    await api.functional.discussionBoard.channels.eraseById(connectionAsNonAdmin, {
      id: output.id,
    });
  });
}

