    body: {
      username: actorUsername,
      email: actorEmail,
      hashed_password: actorPasswordHash,
      display_name: actorDisplayName,
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(actor);

  // 2. Register the target member (to be mentioned)
